let child = null, adminCookie = '', passed = 0, failed = 0;

function startServer() {
  child = spawn(process.execPath, ['-r', './platform-extension.js', 'server.js'], {
    cwd: root,
    env: { ...process.env, DATA_DIR: fixture, ADMIN_PASSWORD: 'final-regression-only', PORT: String(port), RESEND_API_KEY: '', ORDER_EMAIL_FROM: '' },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  child.stdout.on('data', chunk => process.stdout.write(`[server] ${chunk}`));
  child.stderr.on('data', chunk => process.stderr.write(`[server] ${chunk}`));
}
async function stopServer() {
  if (!child || child.exitCode != null) return;
  child.kill('SIGTERM');
  await Promise.race([new Promise(resolve => child.once('exit', resolve)), new Promise(resolve => setTimeout(resolve, 3000))]);
  if (child.exitCode == null) child.kill('SIGKILL');
  child = null;
}
async function waitHealthy() {
  const end = Date.now() + 15000;
  while (Date.now() < end) {
    if (child?.exitCode != null) throw new Error(`Server stopped with exit code ${child.exitCode}`);
    try { const r = await fetch(`${base}/health`); if (r.ok) return; } catch {}
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  throw new Error('Disposable server did not become healthy');
}
async function request(url, { method = 'GET', body, cookie = adminCookie, ok = true } = {}) {
  const r = await fetch(base + url, { method, headers: { ...(body !== undefined ? { 'Content-Type':'application/json' } : {}), ...(cookie ? { Cookie:cookie } : {}) }, body: body === undefined ? undefined : JSON.stringify(body) });
  const raw=await r.text();let data={};try{data=raw?JSON.parse(raw):{};}catch{data={text:raw};}
  if (ok && !r.ok) throw new Error(`${method} ${url}: ${data.error || r.status}`);
  return { status:r.status, ok:r.ok, data, headers:r.headers };
}
